// Rows come in as individual items from Google Sheets node
// Row 0 (first item): meta  — date, total_orders, total_coupon, overall_pct
// Row 1 (second item): header row — skip
// Row 2+ (remaining): coupon data — Coupon, Count, % of Usage, Disc Amt

const items = $input.all();
if (!items || items.length < 3) {
  throw new Error('Email_Data tab has insufficient data — did the Python script run?');
}

const meta = items[0].json;
const dateStr   = String(Object.values(meta)[0] || '');
const totalOrders = Number(Object.values(meta)[1] || 0);
const totalCoupon = Number(Object.values(meta)[2] || 0);
const overallPct  = String(Object.values(meta)[3] || '0.0');

// Coupon rows start at index 2 (skip header at index 1)
const couponRows = items.slice(2).map(it => {
  const v = Object.values(it.json);
  return { display: String(v[0]||''), count: Number(v[1]||0), pct: String(v[2]||'0.0%'), disc: Number(v[3]||0) };
}).filter(r => r.count > 0);

// Date label
const MONTHS = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
let label = dateStr;
try {
  const [y, mo, dy] = dateStr.split('-');
  label = `${parseInt(dy)} ${MONTHS[parseInt(mo)-1]} ${y}`;
} catch(e) { label = dateStr; }

const fmt = n => Math.round(n).toLocaleString('en-IN');

const rows = couponRows.map((r, i) => {
  const isBucket = ['PP (Paid Promotion)','Influencer / Marketing','Others'].includes(r.display);
  const bg  = i % 2 === 0 ? '#ffffff' : '#f8f9fa';
  const fw  = isBucket ? '600' : '400';
  return `<tr style="background:${bg}">
    <td style="padding:9px 16px;border-bottom:1px solid #eee;font-weight:${fw}">${r.display}</td>
    <td style="padding:9px 16px;border-bottom:1px solid #eee;text-align:right">${fmt(r.count)}</td>
    <td style="padding:9px 16px;border-bottom:1px solid #eee;text-align:right">${r.pct}</td>
    <td style="padding:9px 16px;border-bottom:1px solid #eee;text-align:right">&#8377;${fmt(r.disc)}</td>
  </tr>`;
}).join('');

const generatedAt = new Date().toLocaleString('en-IN', { timeZone: 'Asia/Kolkata', hour12: true });

const html = `<!DOCTYPE html>
<html>
<head><meta charset="utf-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/></head>
<body style="margin:0;padding:0;background:#f0f2f5;font-family:Arial,Helvetica,sans-serif">
<table width="100%" cellpadding="0" cellspacing="0" style="padding:32px 16px">
<tr><td align="center">
<table width="660" cellpadding="0" cellspacing="0" style="background:#fff;border-radius:10px;overflow:hidden;box-shadow:0 4px 16px rgba(0,0,0,.10)">

  <tr><td style="background:#1a1a2e;padding:28px 36px">
    <p style="margin:0 0 4px;color:#f5a623;font-size:11px;letter-spacing:3px;text-transform:uppercase">Swiss Beauty Analytics</p>
    <h1 style="margin:0 0 6px;color:#ffffff;font-size:24px;font-weight:700">Daily Coupon Report</h1>
    <p style="margin:0;color:#aaaacc;font-size:14px">&#128197;&nbsp;${label}</p>
  </td></tr>

  <tr><td style="padding:28px 36px 16px">
    <table width="100%" cellpadding="0" cellspacing="0">
    <tr>
      <td style="background:#fff8e1;border:1px solid #ffe082;border-radius:8px;padding:18px 12px;text-align:center;width:23%">
        <div style="font-size:28px;font-weight:700;color:#e65100">${fmt(totalOrders)}</div>
        <div style="font-size:10px;color:#888;margin-top:5px;text-transform:uppercase;letter-spacing:1px">Total Orders</div>
      </td>
      <td width="4%"></td>
      <td style="background:#e8f5e9;border:1px solid #a5d6a7;border-radius:8px;padding:18px 12px;text-align:center;width:23%">
        <div style="font-size:28px;font-weight:700;color:#2e7d32">${fmt(totalCoupon)}</div>
        <div style="font-size:10px;color:#888;margin-top:5px;text-transform:uppercase;letter-spacing:1px">Coupons Used</div>
      </td>
      <td width="4%"></td>
      <td style="background:#e3f2fd;border:1px solid #90caf9;border-radius:8px;padding:18px 12px;text-align:center;width:23%">
        <div style="font-size:28px;font-weight:700;color:#1565c0">${overallPct}%</div>
        <div style="font-size:10px;color:#888;margin-top:5px;text-transform:uppercase;letter-spacing:1px">Overall Usage Rate</div>
        <div style="font-size:9px;color:#aaa;margin-top:2px">coupons / total orders</div>
      </td>
      <td width="4%"></td>
      <td style="background:#f3e5f5;border:1px solid #ce93d8;border-radius:8px;padding:18px 12px;text-align:center;width:23%">
        <div style="font-size:28px;font-weight:700;color:#6a1b9a">&#8377;${fmt(couponRows.reduce((s,r)=>s+r.disc,0))}</div>
        <div style="font-size:10px;color:#888;margin-top:5px;text-transform:uppercase;letter-spacing:1px">Disc Amt &#xD7;0.25</div>
      </td>
    </tr>
    </table>
  </td></tr>

  <tr><td style="padding:8px 36px 32px">
    <p style="margin:0 0 12px;font-size:13px;font-weight:700;color:#1a1a2e;text-transform:uppercase;letter-spacing:1px">Coupon-wise Breakdown</p>
    <table width="100%" cellpadding="0" cellspacing="0" style="font-size:13px;border:1px solid #e0e0e0;border-radius:6px;overflow:hidden">
      <thead>
        <tr style="background:#1a1a2e;color:#fff">
          <th style="padding:11px 16px;text-align:left;font-weight:600;font-size:12px">Coupon</th>
          <th style="padding:11px 16px;text-align:right;font-weight:600;font-size:12px">Count</th>
          <th style="padding:11px 16px;text-align:right;font-weight:600;font-size:12px">% of Usage</th>
          <th style="padding:11px 16px;text-align:right;font-weight:600;font-size:12px">Disc Amt (&#xD7;0.25)</th>
        </tr>
      </thead>
      <tbody>
        ${rows}
        <tr style="background:#f0f0f0;font-weight:700">
          <td style="padding:11px 16px;border-top:2px solid #1a1a2e">TOTAL</td>
          <td style="padding:11px 16px;border-top:2px solid #1a1a2e;text-align:right">${fmt(totalCoupon)}</td>
          <td style="padding:11px 16px;border-top:2px solid #1a1a2e;text-align:right">100.0%</td>
          <td style="padding:11px 16px;border-top:2px solid #1a1a2e;text-align:right">&#8377;${fmt(couponRows.reduce((s,r)=>s+r.disc,0))}</td>
        </tr>
      </tbody>
    </table>
  </td></tr>

  <tr><td style="background:#f8f9fa;padding:14px 36px;border-top:1px solid #eee">
    <p style="margin:0;font-size:11px;color:#aaa">Auto-generated by Swiss Beauty Coupon Automation &middot; ${generatedAt} IST</p>
  </td></tr>

</table>
</td></tr>
</table>
</body></html>`;

return [{ json: {
  to: $('Set Config').first().json.REPORT_TO,
  subject: `Swiss Beauty Coupon Report \u2014 ${label}`,
  html
} }];
